using System.Numerics;
using System.Text.Json;
using System.Text.Json.Serialization;

namespace MSUIClient.World.Encounters;

// ─────────────────────────────────────────────────────────────────────────────
// Authored encounters live on disk as JSON — never as C#.
//
// This is the load-bearing decision of the whole design. The instant an
// encounter is expressed in a real programming language it becomes opaque to
// the tool that is supposed to visualise it, and we are back to reverse-
// engineering compiled behaviour. A JSON document can be read, diffed, reviewed,
// generated by an authoring UI, and eventually emitted as DB rows for a server
// interpreter to execute. Code can do none of that.
//
// An explicit DTO layer sits between the file and the runtime model on purpose:
// the file format has to survive refactors of the records behind it, so the two
// are allowed to drift and the mapping is written out by hand.
// ─────────────────────────────────────────────────────────────────────────────

/// <summary>Vector3 as a compact [x, y, z] array — far easier to eyeball in a diff
/// than three named properties, and it matches how coordinates are quoted in the
/// world DB and in the C++ scripts these documents are transcribed from.</summary>
public sealed class Vector3ArrayConverter : JsonConverter<Vector3>
{
    public override Vector3 Read(ref Utf8JsonReader reader, Type type, JsonSerializerOptions options)
    {
        if (reader.TokenType != JsonTokenType.StartArray)
            throw new JsonException("expected [x, y, z]");
        Span<float> values = stackalloc float[3];
        int count = 0;
        while (reader.Read() && reader.TokenType != JsonTokenType.EndArray)
            if (count < 3) values[count++] = reader.GetSingle();
        return new Vector3(values[0], values[1], values[2]);
    }

    public override void Write(Utf8JsonWriter writer, Vector3 value, JsonSerializerOptions options)
    {
        writer.WriteStartArray();
        writer.WriteNumberValue(value.X);
        writer.WriteNumberValue(value.Y);
        writer.WriteNumberValue(value.Z);
        writer.WriteEndArray();
    }
}

// ── file-format DTOs (mutable, defaulted, tolerant) ──────────────────────────

public sealed class EncounterFileDto
{
    public int SchemaVersion { get; set; } = EncounterSchema.Version;
    public string Key { get; set; } = "";
    public string Name { get; set; } = "";
    public uint PrimaryEntry { get; set; }
    public List<uint>? MemberEntries { get; set; }
    public List<int>? MapIds { get; set; }
    public string? Note { get; set; }
    public ProvenanceDto? Provenance { get; set; }
    public List<string>? Coverage { get; set; }
    public List<ActorDto>? Actors { get; set; }
    public List<PhaseDto>? Phases { get; set; }
    public List<AbilityDto>? Abilities { get; set; }
}

public sealed class ProvenanceDto
{
    public string Source { get; set; } = "authored";
    public string? CoreBuildHash { get; set; }
    public string? DbRevision { get; set; }
    public int? ContentPatch { get; set; }
    public DateTime? CapturedUtc { get; set; }
}

public sealed class ActorDto
{
    public string Key { get; set; } = "";
    public string Name { get; set; } = "";
    public uint Entry { get; set; }
    public EncounterActorRole Role { get; set; } = EncounterActorRole.Friendly;
    public Vector3 Position { get; set; }
    public float Facing { get; set; }
    public float BoundingRadius { get; set; } = 0.5f;
    public float CombatReach { get; set; } = 1.5f;
    public uint Level { get; set; } = 60;
    public uint MaxHealth { get; set; } = 1000;
    public uint DisplayId { get; set; }
    public float DisplayScale { get; set; } = 1f;
    public List<MoveDto>? Moves { get; set; }
    public float Dps { get; set; }
    public RaidJob Job { get; set; } = RaidJob.None;
    public IdleMovementDto? IdleMovement { get; set; }
    public float RunSpeedYdPerSec { get; set; }
    public float WalkSpeedYdPerSec { get; set; }
    public float DetectionRangeYards { get; set; }
    public PlayerRulesDto? PlayerRules { get; set; }
}

public sealed class PlayerRulesDto
{
    public bool AlwaysFaceBoss { get; set; }
    public CombatPlanDto? Plan { get; set; }
}

public sealed class CombatPlanDto
{
    public string Name { get; set; } = "Custom plan";
    public CombatMovementDto? Movement { get; set; }
    public CombatEngagementMode Engagement { get; set; } = CombatEngagementMode.NeverInitiate;
    public List<CombatSupportPriorityDto>? SupportPriorities { get; set; }
    public List<CombatEnemyPriorityDto>? EnemyPriorities { get; set; }
    public List<CombatResponsibility>? Responsibilities { get; set; }
    public CombatResourcePolicyDto? Resources { get; set; }
    public CombatFallback Fallback { get; set; } = CombatFallback.ClassDefaults;
    public List<CombatAbilityIntentDto>? Rotation { get; set; }
    public uint ClassId { get; set; }
}

public sealed class CombatAbilityIntentDto
{
    public uint SpellId { get; set; }
    public string Name { get; set; } = "";
    public bool Enabled { get; set; } = true;
}

public sealed class CombatMovementDto
