    public List<TransitionDto>? Transitions { get; set; }
    public string? Note { get; set; }
}

/// <summary>Loads and saves authored encounter documents.</summary>
public sealed class EncounterLibrary
{
    public static readonly JsonSerializerOptions JsonOptions = new()
    {
        PropertyNameCaseInsensitive = true,
        PropertyNamingPolicy = JsonNamingPolicy.CamelCase,
        WriteIndented = true,
        DefaultIgnoreCondition = JsonIgnoreCondition.WhenWritingNull,
        Converters = { new JsonStringEnumConverter(), new Vector3ArrayConverter() },
    };

    private readonly Dictionary<string, EncounterDefinition> _byKey = new(StringComparer.OrdinalIgnoreCase);
    private readonly Dictionary<uint, string> _byEntry = [];
    private readonly List<string> _errors = [];

    public string Directory { get; }
    public IReadOnlyCollection<EncounterDefinition> All => _byKey.Values;
    public IReadOnlyList<string> Errors => _errors;
    public int Count => _byKey.Count;

    public EncounterLibrary(string directory) => Directory = directory;

    public EncounterDefinition? Get(string key) => _byKey.GetValueOrDefault(key);

    /// <summary>An authored document for this creature entry, if one exists. Checked
    /// before falling back to a DB-derived definition.</summary>
    public EncounterDefinition? ForEntry(uint entry) =>
        _byEntry.TryGetValue(entry, out string? key) ? _byKey.GetValueOrDefault(key) : null;

    /// <summary>Reload every *.json in the directory. Bad documents are collected in
    /// <see cref="Errors"/> rather than thrown — one broken file must not take the
    /// whole library down.</summary>
    public int Reload()
    {
        _byKey.Clear();
        _byEntry.Clear();
        _errors.Clear();
        if (!System.IO.Directory.Exists(Directory)) return 0;

        foreach (string path in System.IO.Directory.EnumerateFiles(Directory, "*.json"))
        {
            try
            {
                EncounterFileDto? dto = JsonSerializer.Deserialize<EncounterFileDto>(
                    File.ReadAllText(path), JsonOptions);
                if (dto is null) { _errors.Add($"{Path.GetFileName(path)}: empty document"); continue; }
                if (dto.SchemaVersion != EncounterSchema.Version)
                {
                    _errors.Add($"{Path.GetFileName(path)}: schemaVersion {dto.SchemaVersion} " +
                                $"(this build reads {EncounterSchema.Version})");
                    continue;
                }
                EncounterDefinition definition = FromDto(dto);
                _byKey[definition.Key] = definition;
                _byEntry[definition.PrimaryEntry] = definition.Key;
                foreach (uint member in definition.MemberEntries ?? [])
                    _byEntry.TryAdd(member, definition.Key);
            }
            catch (Exception ex)
            {
                _errors.Add($"{Path.GetFileName(path)}: {ex.Message}");
            }
        }
        return _byKey.Count;
    }

    public void Save(EncounterDefinition definition, string? fileName = null)
    {
        System.IO.Directory.CreateDirectory(Directory);
        string path = Path.Combine(Directory, fileName ?? $"{definition.Key}.json");
        File.WriteAllText(path, JsonSerializer.Serialize(ToDto(definition), JsonOptions));
    }

    // ── DTO ⇄ model ──────────────────────────────────────────────────────────

    public static EncounterDefinition FromDto(EncounterFileDto dto)
    {
        EncounterCoverage coverage = EncounterCoverage.None;
        foreach (string flag in dto.Coverage ?? [])
            if (Enum.TryParse(flag, ignoreCase: true, out EncounterCoverage parsed)) coverage |= parsed;

        return new EncounterDefinition(
            Key: dto.Key,
            Name: dto.Name,
            PrimaryEntry: dto.PrimaryEntry,
            Phases: (dto.Phases ?? []).Select(FromDto).ToArray(),
            Abilities: (dto.Abilities ?? []).Select(FromDto).ToArray(),
            Provenance: new EncounterProvenance(
                dto.Provenance?.Source ?? "authored",
                dto.Provenance?.CoreBuildHash,
                dto.Provenance?.DbRevision,
                dto.Provenance?.ContentPatch,
                dto.Provenance?.CapturedUtc),
            Coverage: coverage,
            MemberEntries: dto.MemberEntries,
            MapIds: dto.MapIds,
            Actors: (dto.Actors ?? []).Select(FromDto).ToArray(),
            SchemaVersion: dto.SchemaVersion,
            Note: dto.Note);
    }

    private static EncounterActorSpec FromDto(ActorDto dto) => new(
        dto.Key, dto.Name, dto.Entry, dto.Role, dto.Position, dto.Facing,
        dto.BoundingRadius, dto.CombatReach, dto.Level, dto.MaxHealth,
        dto.DisplayId, dto.DisplayScale,
        dto.Moves?.Select(m => new TimedMove(m.TimeMs, m.Position, m.Anchor, m.PhaseKey,
            m.ArrivalFacing ?? float.NaN, m.Teleport)).ToArray(),
        dto.Dps, dto.Job,
        dto.IdleMovement is { } idle
            ? new IdleMovementSpec(idle.Kind, idle.WanderYards,
                idle.Points?.Select(p => new IdleWaypoint(p.Position, p.WaitMs)).ToArray(),
                idle.Note)
            : null,
        dto.RunSpeedYdPerSec, dto.WalkSpeedYdPerSec, dto.DetectionRangeYards,
        dto.PlayerRules is { } rules
            ? new EncounterPlayerRules(rules.AlwaysFaceBoss, CombatPlanFromDto(rules.Plan))
            : null);

    /// <summary>Single file-format mapping shared by authored encounter documents and
    /// the per-character combat-plan store.</summary>
    public static CombatPlan? CombatPlanFromDto(CombatPlanDto? dto) => dto is null ? null : new CombatPlan(
        dto.Name,
        dto.Movement is { } movement
            ? new CombatMovementPlan(movement.Mode, FromDto(movement.Anchor),
                movement.MinRangeYards, movement.MaxRangeYards,
                movement.FacePrimaryEnemy)
            : null,
        dto.Engagement,
        dto.SupportPriorities?.Select(priority => new CombatSupportPriority(
            FromDto(priority.Target) ?? CombatSubject.LowestHealth,
            priority.OnlyWhenBelowHealthPercent, priority.Enabled)).ToArray(),
        dto.EnemyPriorities?.Select(priority =>
            new CombatEnemyPriority(priority.Kind, priority.Enabled)).ToArray(),
        dto.Responsibilities?.ToArray(),
        dto.Resources is { } resources
            ? new CombatResourcePolicy(resources.ReservePercent,
                resources.EmergencyHealthPercent, resources.SaveMajorCooldowns)
            : null,
        dto.Fallback,
        dto.Rotation?.Select(intent =>
            new CombatAbilityIntent(intent.SpellId, intent.Name, intent.Enabled)).ToArray(),
        dto.ClassId);

    private static CombatSubject? FromDto(CombatSubjectDto? dto) => dto is null ? null :
        new CombatSubject(dto.Kind, dto.Role, Math.Max(dto.Ordinal, 1));

    private static EncounterPhase FromDto(PhaseDto dto) => new(
        dto.Key, dto.Name,
        (dto.Transitions ?? []).Select(FromDto).ToArray(),
        (dto.OnEnter ?? []).Select(FromDto).ToArray(),
        dto.CasterFlying, dto.MeleeEnabled, dto.Note);

    private static EncounterTransition FromDto(TransitionDto dto) => new(
        dto.ToPhase, FromDto(dto.Trigger), dto.Fidelity,
        (dto.Steps ?? []).Select(FromDto).ToArray(),
        (dto.Sources ?? []).Select(FromDto).ToArray(),
        dto.Note);

    private static EncounterAbility FromDto(AbilityDto dto) => new(
        dto.Key, dto.Name, dto.SpellId,
        FromDto(dto.Trigger), FromDto(dto.Timing), FromDto(dto.Target), FromDto(dto.Geometry),
        dto.Fidelity, dto.Phases, dto.ChancePercent, dto.CastTimeMs,
        (dto.Steps ?? []).Select(FromDto).ToArray(),
        (dto.Sources ?? []).Select(FromDto).ToArray(),
        dto.Note);

    private static EncounterStep FromDto(StepDto dto) => new(
        dto.Kind, dto.DurationMs, dto.Point, dto.SpellId, dto.Entry,
        dto.Count, dto.Value, dto.Flag, dto.PhaseKey, dto.Note, dto.DisplayId);

    private static EncounterSourceRef FromDto(SourceDto dto) => new(dto.Kind, dto.Location, dto.Detail);

    private static EncounterTriggerSpec FromDto(TriggerDto? dto) => dto is null
        ? EncounterTriggerSpec.Manual
        : new EncounterTriggerSpec(dto.Kind, dto.Threshold, dto.Param1, dto.Param2);

    private static EncounterTiming FromDto(TimingDto? dto) => dto is null
        ? EncounterTiming.Never
        : new EncounterTiming(dto.InitialMinMs, dto.InitialMaxMs, dto.RepeatMinMs, dto.RepeatMaxMs);

    private static EncounterTargetSpec FromDto(TargetDto? dto) => dto is null
        ? EncounterTargetSpec.Victim
        : new EncounterTargetSpec(dto.Kind, dto.Point, dto.Param1);

    private static EncounterGeometrySpec FromDto(GeometryDto? dto) => dto is null
        ? EncounterGeometrySpec.None
        : new EncounterGeometrySpec(dto.Kind, dto.Radius, dto.ConeDegrees, dto.Width,
            dto.ProjectileSpeed, dto.DurationMs, dto.Points, dto.PointSpellIds);

    public static EncounterFileDto ToDto(EncounterDefinition definition) => new()
    {
        SchemaVersion = definition.SchemaVersion,
        Key = definition.Key,
        Name = definition.Name,
        PrimaryEntry = definition.PrimaryEntry,
        MemberEntries = definition.MemberEntries?.ToList(),
        MapIds = definition.MapIds?.ToList(),
        Note = definition.Note,
        Coverage = definition.Coverage == EncounterCoverage.None
            ? null
            : definition.Coverage.ToString().Split(", ").ToList(),
        Provenance = new ProvenanceDto
        {
            Source = definition.Provenance.Source,
            CoreBuildHash = definition.Provenance.CoreBuildHash,
            DbRevision = definition.Provenance.DbRevision,
            ContentPatch = definition.Provenance.ContentPatch,
            CapturedUtc = definition.Provenance.CapturedUtc,
        },
        Actors = definition.Actors?.Select(a => new ActorDto
        {
            Key = a.Key, Name = a.Name, Entry = a.Entry, Role = a.Role,
            Position = a.Position, Facing = a.Facing, BoundingRadius = a.BoundingRadius,
            CombatReach = a.CombatReach, Level = a.Level, MaxHealth = a.MaxHealth,
            DisplayId = a.DisplayId, DisplayScale = a.DisplayScale,
            Moves = a.Moves?.Select(m => new MoveDto
            {
                TimeMs = m.TimeMs, Position = m.Position, Anchor = m.Anchor,
                PhaseKey = m.PhaseKey,
                ArrivalFacing = m.HasArrivalFacing ? m.ArrivalFacing : null,
                Teleport = m.Teleport,
            }).ToList(),
            Dps = a.Dps,
            Job = a.Job,
            IdleMovement = a.IdleMovement is { } idle
                ? new IdleMovementDto
                {
                    Kind = idle.Kind, WanderYards = idle.WanderYards, Note = idle.Note,
                    Points = idle.Points?.Select(p => new IdleWaypointDto
                    { Position = p.Position, WaitMs = p.WaitMs }).ToList(),
                }
                : null,
            RunSpeedYdPerSec = a.RunSpeedYdPerSec,
            WalkSpeedYdPerSec = a.WalkSpeedYdPerSec,
            DetectionRangeYards = a.DetectionRangeYards,
            PlayerRules = a.PlayerRules is { } rules
                ? new PlayerRulesDto
                {
                    AlwaysFaceBoss = rules.AlwaysFaceBoss,
                    Plan = CombatPlanToDto(rules.Plan),
                }
                : null,
        }).ToList(),
        Phases = definition.Phases.Select(p => new PhaseDto
        {
            Key = p.Key, Name = p.Name, CasterFlying = p.CasterFlying,
            MeleeEnabled = p.MeleeEnabled, Note = p.Note,
            OnEnter = p.OnEnter?.Select(ToDto).ToList(),
            Transitions = p.Transitions?.Select(t => new TransitionDto
            {
                ToPhase = t.ToPhase, Fidelity = t.Fidelity, Note = t.Note,
                Trigger = ToDto(t.Trigger),
                Steps = t.Steps?.Select(ToDto).ToList(),
                Sources = t.Sources?.Select(ToDto).ToList(),
            }).ToList(),
        }).ToList(),
        Abilities = definition.Abilities.Select(a => new AbilityDto
        {
            Key = a.Key, Name = a.Name, SpellId = a.SpellId, Fidelity = a.Fidelity,
            Phases = a.Phases?.ToList(), ChancePercent = a.ChancePercent,
            CastTimeMs = a.CastTimeMs, Note = a.Note,
            Trigger = ToDto(a.Trigger), Timing = ToDto(a.Timing),
            Target = ToDto(a.Target), Geometry = ToDto(a.Geometry),
            Steps = a.Steps?.Select(ToDto).ToList(),
            Sources = a.Sources?.Select(ToDto).ToList(),
        }).ToList(),
    };

    /// <summary>Single model-to-file mapping shared by authored encounter documents and
    /// the per-character combat-plan store.</summary>
    public static CombatPlanDto? CombatPlanToDto(CombatPlan? plan) => plan is null ? null : new CombatPlanDto
    {
        Name = plan.Name,
        Movement = plan.Movement is { } movement
            ? new CombatMovementDto
            {
                Mode = movement.Mode,
                Anchor = ToDto(movement.Anchor),
                MinRangeYards = movement.MinRangeYards,
                MaxRangeYards = movement.MaxRangeYards,
                FacePrimaryEnemy = movement.FacePrimaryEnemy,
            }
            : null,
        Engagement = plan.Engagement,
        SupportPriorities = plan.SupportPriorities?.Select(priority =>
            new CombatSupportPriorityDto
            {
                Target = ToDto(priority.Target) ?? new CombatSubjectDto(),
                OnlyWhenBelowHealthPercent = priority.OnlyWhenBelowHealthPercent,
                Enabled = priority.Enabled,
            }).ToList(),
        EnemyPriorities = plan.EnemyPriorities?.Select(priority =>
            new CombatEnemyPriorityDto
            {
                Kind = priority.Kind,
                Enabled = priority.Enabled,
            }).ToList(),
        Responsibilities = plan.Responsibilities?.ToList(),
        Resources = plan.Resources is { } resources
            ? new CombatResourcePolicyDto
            {
                ReservePercent = resources.ReservePercent,
                EmergencyHealthPercent = resources.EmergencyHealthPercent,
                SaveMajorCooldowns = resources.SaveMajorCooldowns,
            }
            : null,
        Fallback = plan.Fallback,
        Rotation = plan.Rotation?.Select(intent => new CombatAbilityIntentDto
        {
            SpellId = intent.SpellId,
            Name = intent.Name,
            Enabled = intent.Enabled,
        }).ToList(),
        ClassId = plan.ClassId,
    };

    private static CombatSubjectDto? ToDto(CombatSubject? subject) => subject is null ? null :
        new CombatSubjectDto
        {
            Kind = subject.Kind,
            Role = subject.Role,
            Ordinal = subject.Ordinal,
        };

    private static StepDto ToDto(EncounterStep s) => new()
    {
        Kind = s.Kind, DurationMs = s.DurationMs, Point = s.Point, SpellId = s.SpellId,
        Entry = s.Entry, Count = s.Count, Value = s.Value, Flag = s.Flag,
        PhaseKey = s.PhaseKey, Note = s.Note, DisplayId = s.DisplayId,
    };

    private static SourceDto ToDto(EncounterSourceRef s) =>
        new() { Kind = s.Kind, Location = s.Location, Detail = s.Detail };

    private static TriggerDto ToDto(EncounterTriggerSpec t) =>
        new() { Kind = t.Kind, Threshold = t.Threshold, Param1 = t.Param1, Param2 = t.Param2 };

    private static TimingDto ToDto(EncounterTiming t) => new()
    {
        InitialMinMs = t.InitialMinMs, InitialMaxMs = t.InitialMaxMs,
        RepeatMinMs = t.RepeatMinMs, RepeatMaxMs = t.RepeatMaxMs,
    };

    private static TargetDto ToDto(EncounterTargetSpec t) =>
        new() { Kind = t.Kind, Point = t.Point, Param1 = t.Param1 };

    private static GeometryDto ToDto(EncounterGeometrySpec g) => new()
    {
        Kind = g.Kind, Radius = g.Radius, ConeDegrees = g.ConeDegrees, Width = g.Width,
        ProjectileSpeed = g.ProjectileSpeed, DurationMs = g.DurationMs,
        Points = g.Points?.ToList(), PointSpellIds = g.PointSpellIds?.ToList(),
    };
}
